import{at as e,n as t,rt as n,yt as r}from"./chunks/framework.ne95vkW4.js";var i=JSON.parse(`{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"development/contributing.md","filePath":"development/contributing.md","lastUpdated":1787332538000}`),a={name:`development/contributing.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to “Contributing”">​</a></h1><p>Thank you for considering contributing to <code>emgr</code>!</p><h2 id="how-to-contribute" tabindex="-1">How to contribute <a class="header-anchor" href="#how-to-contribute" aria-label="Permalink to “How to contribute”">​</a></h2><ul><li><strong>Bug reports</strong>: open an issue on GitHub.</li><li><strong>Feature requests</strong>: open an issue to discuss it first.</li><li><strong>Code contributions</strong>: pull requests are welcome.</li><li><strong>Documentation improvements</strong>: if you find a gap or an error, open an issue or a pull request.</li></ul><h2 id="development-setup" tabindex="-1">Development setup <a class="header-anchor" href="#development-setup" aria-label="Permalink to “Development setup”">​</a></h2><p>See <a href="./../getting-started/installation">Installation</a> for cloning the repository, picking a Cargo feature set (there is no default storage backend - <code>local_fs</code>/<code>s3</code>/<code>in_memory</code>, plus <code>otel</code> optionally), and the two environment variables the service requires before it will start (<code>SIGNING_KEY</code>/<code>SIGNING_SALT</code> or <code>ALLOW_UNSIGNED_REQUESTS</code>, and, on <code>otel</code> builds, <code>METRICS_AUTH_TOKEN</code> or <code>ALLOW_UNAUTHENTICATED_METRICS</code>).</p><h2 id="code-style" tabindex="-1">Code style <a class="header-anchor" href="#code-style" aria-label="Permalink to “Code style”">​</a></h2><p>This project follows standard Rust formatting - run <code>cargo fmt</code> before submitting a pull request. There&#39;s no repo-specific <code>rustfmt.toml</code>, so <code>rustfmt</code>&#39;s defaults apply.</p><p>Clippy is checked in CI (<code>.github/workflows/ci.yml</code>&#39;s <code>clippy</code> job), run against a single representative feature set:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clippy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local_fs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-targets</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> warnings</span></span></code></pre></div><p>That job is currently <code>continue-on-error: true</code> (non-blocking) while an existing warning backlog (<code>dead_code</code>, <code>collapsible_if</code>, <code>manual_saturating_arithmetic</code>, doc-list-item indentation, and a few others - run it locally to see the current set) gets cleared - see the job&#39;s own comment in <code>ci.yml</code> for the tracked issue. Still run it locally and avoid adding to the backlog; <code>.clippy.toml</code> sets stricter-than-default <code>too-many-arguments-threshold</code> and <code>cognitive-complexity-threshold</code> because this service decodes attacker-supplied image bytes, and an accidental panic in a request path is a denial-of-service primitive - keep the bar low enough for new <code>unwrap()</code>s to stand out in review.</p><p><code>cargo-deny</code> (advisories, licenses, bans, sources - see <code>deny.toml</code>) also runs in CI and <em>is</em> blocking:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deny</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><h2 id="commit-messages" tabindex="-1">Commit messages <a class="header-anchor" href="#commit-messages" aria-label="Permalink to “Commit messages”">​</a></h2><p>Follow <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a> (<code>feat:</code>, <code>fix:</code>, <code>perf:</code>, <code>docs:</code>, <code>chore:</code>, ...) - this is what the project&#39;s own history already uses, and it keeps <code>git log --oneline</code> skimmable for changelog reconstruction.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>feat: add support for WEBP output format</span></span>
<span class="line"><span></span></span>
<span class="line"><span>This commit introduces the ability to output images in WEBP format.</span></span>
<span class="line"><span>- Added WEBP encoding option.</span></span>
<span class="line"><span>- Updated API documentation.</span></span></code></pre></div><h2 id="pull-request-process" tabindex="-1">Pull request process <a class="header-anchor" href="#pull-request-process" aria-label="Permalink to “Pull request process”">​</a></h2><ol><li><strong>Fork the repository</strong> and create your branch from <code>main</code>.</li><li><strong>Make your changes.</strong></li><li><strong>Add tests</strong> for your changes - see <a href="./testing">Testing</a> for the project&#39;s actual test patterns (real backends over mocks, tests co-located in <code>#[cfg(test)]</code> modules or in <code>tests/</code>).</li><li><strong>If you add a new environment variable</strong>, document it in <a href="./../getting-started/configuration">Configuration</a> - CI&#39;s <code>docs-env-drift</code> job (<code>.github/scripts/check_env_docs.py</code>) fails the build if <code>src/modules/env/env.rs</code> and that page drift apart in either direction.</li><li><strong>Run the relevant test matrix locally</strong> - at minimum the feature set you touched; CI runs all three of <code>local_fs</code>, <code>s3</code>, and <code>local_fs,otel</code> separately (see <a href="./testing">Testing</a>).</li><li><strong>Format and lint</strong>: <code>cargo fmt</code>, <code>cargo clippy --features local_fs --all-targets -- -D warnings</code>, <code>cargo deny check</code>.</li><li><strong>Commit</strong> using Conventional Commits.</li><li><strong>Push your branch</strong> to your fork.</li><li><strong>Open a pull request</strong> against <code>main</code>, with a clear description of what changed and why.</li></ol><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to “License”">​</a></h2><p>By contributing, you agree that your contributions will be licensed under the project&#39;s <a href="./../about/license">MIT license</a>.</p>`,21)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};